{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    sum_min = sum(s['minimum'] for s in segments)
    sum_cap = sum(s['capacity'] for s in segments)

    if budget < sum_min or budget > sum_cap:
        raise ValueError('Budget out of feasible range')

    allocations = [s['minimum'] for s in segments]
    allocated = sum_min
    remain = budget - allocated

    while remain > 0:
        best_idx = None
        best_ratio = -1.0
        for i, s in enumerate(segments):
            ratio = s['importance'] / (allocations[i] + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        allocations[best_idx] += 1
        remain -= 1

    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)

    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
